'use strict';
const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)];
const MIN={inf:{n:'Мин. Инф.',full:'Министерство Инфраструктуры',c:'var(--inf)',d:'Строительство, дороги, общественные объекты и развитие инфраструктуры.'},eco:{n:'Мин. Эко.',full:'Министерство Экономики',c:'var(--eco)',d:'Налоги, бочки, торговля и экономика.'},bez:{n:'Мин. Без.',full:'Министерство Безопасности',c:'var(--bez)',d:'Полиция, спецназ, группа быстрого реагирования и безопасность жителей.'}};
const config=window.PORTAL_CONFIG||{}, DEMO=!config.supabaseUrl&&!config.supabaseAnonKey;
const KEY='presidentPortal_v2', AUTHKEY=KEY+'_auth';
const iso=d=>new Intl.DateTimeFormat('sv-SE',{timeZone:'Europe/Moscow',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date(d));
const today0=()=>new Date(iso(Date.now())+'T00:00:00+03:00');
const fmtD=s=>new Date(s).toLocaleDateString('ru-RU',{timeZone:'Europe/Moscow'});
const fmtDT=t=>new Date(t).toLocaleString('ru-RU',{timeZone:'Europe/Moscow',day:'2-digit',month:'short',hour:'2-digit',minute:'2-digit'});
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const safeUrl=s=>{try{const u=new URL(s);return /^https?:$/.test(u.protocol)?u.href:'#'}catch{return '#'}};
const uid=()=>crypto.randomUUID();
// Empty by default: no invented identities, publications, tax rows or election dates.
const empty=()=>({settings:{name:'Портал',ip:'',pres:'Не назначен',president_id:null,term:''},players:[],news:[],reports:{inf:[],eco:[],bez:[]},complaints:[],law:null,lawDraft:null,taxes:[]});
function cleanLegacyDemo(data){
 const base=empty(),old=data&&typeof data==='object'?data:base;
 const out={...base,...old,settings:{...base.settings,...old.settings},reports:{...base.reports,...old.reports}};
 const synthetic=new Set(['demo-president','demo-eco','demo-inf','demo-bez','demo-player']);
 const legacy=(out.players||[]).some(p=>synthetic.has(p.id));
 out.players=(out.players||[]).filter(p=>!synthetic.has(p.id));
 const seededTax=t=>legacy&&t.paid===true&&!t.note&&!(t.images||[]).length&&!out.players.some(p=>p.nick.toLowerCase()===String(t.nick).toLowerCase())&&((t.nick==='ccotan'&&String(t.num)==='1'&&t.upd==='2026-04-07')||(t.nick==='GAZAN'&&String(t.num)==='2'&&t.upd==='2026-04-08'));
 const removedTaxIds=new Set((out.taxes||[]).filter(seededTax).map(t=>t.id));
 out.taxes=(out.taxes||[]).filter(t=>!removedTaxIds.has(t.id));
 const keep=r=>!synthetic.has(r.author_id)&&!synthetic.has(r.actor_id)&&!synthetic.has(r.user_id);
 for(const key of ['news','complaints','tasks','complaintMessages','notifications','audit'])out[key]=(out[key]||[]).filter(keep);
 for(const k of Object.keys(out.reports))out.reports[k]=(out.reports[k]||[]).filter(keep);
 const complaintIds=new Set(out.complaints.map(c=>c.id));
 out.complaintMessages=out.complaintMessages.filter(m=>complaintIds.has(m.complaint_id));
 out.notifications=out.notifications.filter(n=>![...removedTaxIds].some(id=>String(n.dedupe_key||'').startsWith('tax:'+id+':')));
 if(out.law&&!keep(out.law))out.law=null;
 if(out.lawDraft&&!keep(out.lawDraft))out.lawDraft=null;
 const president=out.players.find(p=>p.id===out.settings.president_id);
 if(!president)Object.assign(out.settings,{pres:'Не назначен',president_id:null,term:''});else out.settings.pres=president.nick;
 if(legacy){if(out.settings.name==='state')out.settings.name='Портал';if(out.settings.ip==='play.example.ru')out.settings.ip='';}
 out.dataVersion=45;return out;
}
let S=empty(),session=null,me=null,chan='inf',cType='player',cFilt='all',busy=false,authRecovery=false,lastFocus=null,refreshPromise=null;
try{if(DEMO){S=cleanLegacyDemo(JSON.parse(localStorage.getItem(KEY)||'null'));localStorage.setItem(KEY,JSON.stringify(S));const id=sessionStorage.getItem(KEY+'_demo');if(id&&S.players.some(p=>p.id===id))session={user:{id}};else sessionStorage.removeItem(KEY+'_demo');}else session=JSON.parse(localStorage.getItem(AUTHKEY)||'null')}catch{S=empty()}
const P=n=>S.players.find(p=>p.nick.toLowerCase()===String(n).toLowerCase());
const isPres=()=>!!session?.user?.id&&session.user.id===S.settings.president_id;
const inMin=m=>!!session&&S.players.some(p=>p.id===session.user.id&&p.min===m);
const canJudge=()=>isPres()||inMin('bez');
const canTax=()=>isPres()||inMin('eco');
const canReports=()=>isPres()||Object.keys(MIN).some(inMin);
const ava=(n,cls='ava')=>/^[A-Za-z0-9_]{2,16}$/.test(n||'')?`<img class="${cls}" src="https://mc-heads.net/avatar/${encodeURIComponent(n)}/128" data-nick="${esc(n)}" data-avatar-step="0" width="32" height="32" alt="Minecraft-голова ${esc(n)}" title="${esc(n)}" loading="lazy" referrerpolicy="no-referrer" onerror="avatarFallback(this)">`:`<span class="${cls} neutral-avatar" aria-hidden="true">${icon('user')}</span>`;
function roleTag(n){if(n===S.settings.pres)return '<span class="tag t-pres">Президент</span>';const p=P(n);return p?.min?`<span class="tag t-${p.min}">${p.head?'Глава ':''}${MIN[p.min].n}</span>`:'<span class="tag t-pl">Игрок</span>'}
function toast(t){const e=$('#toast');e.textContent=t;e.classList.add('on');clearTimeout(e._t);e._t=setTimeout(()=>e.classList.remove('on'),5000)}
function modal(h){$('#modalBody').classList.remove('editor-modal','case-modal');lastFocus=document.activeElement;$('#modalBody').innerHTML='<button class="modal-close" aria-label="Закрыть" onclick="closeModal()">×</button>'+h;$('#modal').classList.add('open');setTimeout(()=>$('#modalBody input, #modalBody select, #modalBody button')?.focus(),0);labelInputs();}
function closeModal(){$('#modal').classList.remove('open');$('#modalBody').classList.remove('editor-modal','case-modal');editor=null;lastFocus?.focus()}
function labelInputs(){ $$('label').forEach(l=>{const e=l.nextElementSibling;if(e?.matches('input,select,textarea')&&e.id)l.htmlFor=e.id});$$('input,select,textarea').forEach(e=>{if(!e.labels?.length&&!e.hasAttribute('aria-label'))e.setAttribute('aria-label',e.placeholder||e.id||'Поле ввода')});}
function taxInfo(t){const end=new Date(t.upd+'T00:00:00+03:00');end.setUTCDate(end.getUTCDate()+7);const left=Math.round((end-today0())/864e5);return {end,left,st:t.paid&&left>0?(left<=2?'soon':'act'):'exp'}}
function go(p){location.hash=p}
function route(){const caseMatch=/^case\/([A-Za-z0-9-]+)$/.exec(location.hash.slice(1));if(caseMatch)activeCase=caseMatch[1];let p=caseMatch?'case':location.hash.slice(1)||'home';if(p==='decrees'){p='news';history.replaceState(null,'','#news')}if(!['home','news','mins','reports','complaints','case','taxes','law','register','cabinet','notifications','tasks','team','history','admin'].includes(p)||(p==='admin'&&!isPres())||(p==='reports'&&!canReports())||(['cabinet','notifications'].includes(p)&&!me)||(p==='tasks'&&!canReports())||(p==='team'&&!canTeam())||(p==='history'&&!isPres()))p='home';$$('.page').forEach(e=>e.classList.toggle('on',e.id==='p-'+p));$$('.links a').forEach(a=>a.classList.toggle('on',a.dataset.p===p));$('#links').classList.remove('open');window.scrollTo(0,0);render();labelInputs();renderRegistrationNotice();if(p==='case')renderCasePage(false);startCasePolling(p==='case');}
function userClick(e){if(!me)return loginModal();e.stopPropagation();$('#links').classList.remove('open');$('#umenu').classList.toggle('open')}
document.addEventListener('click',()=>$('#umenu')?.classList.remove('open'));
function storeAuth(s){session=s?{access_token:s.access_token,refresh_token:s.refresh_token,expires_at:s.expires_at,expires_in:s.expires_in,token_type:s.token_type,user:s.user}:null;if(session)localStorage.setItem(AUTHKEY,JSON.stringify(session));else localStorage.removeItem(AUTHKEY)}
async function auth(path,data,token){const r=await fetch(config.supabaseUrl.replace(/\/$/,'')+'/auth/v1/'+path,{method:'POST',headers:{apikey:config.supabaseAnonKey,'Content-Type':'application/json',...(token?{Authorization:'Bearer '+token}:{})},body:JSON.stringify(data)});const out=await r.json().catch(()=>({}));if(!r.ok)throw new Error(out.msg||out.error_description||out.message||'Ошибка авторизации');return out;}
async function validToken(){if(session?.refresh_token&&Date.now()>((session.expires_at||0)*1000-60000)){if(!refreshPromise)refreshPromise=auth('token?grant_type=refresh_token',{refresh_token:session.refresh_token}).then(s=>storeAuth({...s,expires_at:Math.floor(Date.now()/1000)+s.expires_in})).finally(()=>refreshPromise=null);await refreshPromise}return session?.access_token||null;}
async function api(path,method='GET',body,extra={}){if(!config.supabaseUrl||!config.supabaseAnonKey)throw new Error('Заполните оба поля config.js');const token=await validToken();const r=await fetch(config.supabaseUrl.replace(/\/$/,'')+'/rest/v1/'+path,{method,headers:{apikey:config.supabaseAnonKey,...(token?{Authorization:'Bearer '+token}:{}),'Content-Type':'application/json',...extra},...(body===undefined?{}:{body:JSON.stringify(body)})});const out=await r.json().catch(()=>null);if(!r.ok)throw new Error(out?.message||'Ошибка сервера '+r.status);return out;}
async function rows(table){let result=[];for(let offset=0;;offset+=1000){const chunk=await api(`${table}?select=*&order=id&limit=1000&offset=${offset}`);result.push(...chunk);if(chunk.length<1000)return result;if(result.length>=50000)throw new Error('Реестр слишком большой. Нужна серверная пагинация.')}}
async function loadData(){if(DEMO){me=S.players.find(p=>p.id===session?.user?.id)?.nick||null;normaliseV3();demoSyncNotices();await loadDiscordIdentity();return}if(session?.user?.id)await api('rpc/portal_action','POST',{action:'sync_notifications',payload:{}});const [settings,players,news,reports,complaints,taxes,laws,drafts,tasks,messages,notifications,audit]=await Promise.all(['portal_settings','profiles','news','reports','complaints','taxes','constitution','law_drafts','ministry_tasks','complaint_messages','notifications','action_log'].map(rows));const st=settings[0];S={settings:{name:st?.name||'Портал',ip:st?.ip||'',pres:players.find(p=>p.id===st?.president_id)?.nick||'Не назначен',president_id:st?.president_id,term:st?.term?new Date(new Date(st.term).getTime()+3*3600e3).toISOString().slice(0,16):''},players,news:news.map(n=>({...n,t:new Date(n.created_at).getTime()})),reports:{inf:[],eco:[],bez:[]},complaints:complaints.map(c=>({...c,t:new Date(c.created_at).getTime()})),taxes,tasks,complaintMessages:messages,notifications,audit,law:laws[0]?{...laws[0],t:new Date(laws[0].published_at).getTime()}:null,lawDraft:drafts[0]||null};for(const r of reports)S.reports[r.channel].push({...r,t:new Date(r.created_at).getTime()});me=players.find(p=>p.id===session?.user?.id)?.nick||null;await loadDiscordIdentity();}
async function refreshPortal(){if(busy)return;$('#syncLabel').textContent='Обновление…';try{await loadData();route();$('#syncLabel').textContent='Обновлено '+fmtDT(Date.now())+' · МСК'}catch(e){$('#syncLabel').textContent='Нет связи с базой';toast('Данные не обновлены: '+e.message)}}
async function mutate(action,payload={}){if(busy)return false;busy=true;const buttons=$$('button');buttons.forEach(b=>b.disabled=true);try{if(DEMO){const before=structuredClone(S);try{demoAction(action,payload);localStorage.setItem(KEY,JSON.stringify(S))}catch(e){S=before;throw e}}else await api('rpc/portal_action','POST',{action,payload});await loadData();render();labelInputs();$('#syncLabel').textContent='Сохранено '+fmtDT(Date.now());return true}catch(e){toast('Не удалось сохранить: '+e.message);return false}finally{busy=false;buttons.forEach(b=>b.disabled=false)}}
function demoActionV2(a,p){if(!session)throw new Error('Сначала войдите');const by={author:me,author_id:session.user.id};switch(a){
case 'law_draft':if(!isPres())throw new Error('Только Президент');S.lawDraft={...p};break;
case 'law_publish':if(!isPres())throw new Error('Только Президент');S.lawDraft={...p};S.law={...p,...by,t:Date.now(),published_at:new Date().toISOString()};break;
case 'news_update':if(!isPres())throw new Error('Только Президент');Object.assign(S.news.find(n=>n.id===p.id),p,{updated_at:new Date().toISOString()});break;
case 'news_add':if(!isPres())throw new Error('Только Президент');S.news.push({id:uid(),...p,...by,t:Date.now()});break;
case 'news_pin':case 'news_delete':if(!isPres())throw new Error('Только Президент');if(a==='news_pin')S.news.find(x=>x.id===p.id).pin=p.pin;else S.news=S.news.filter(x=>x.id!==p.id);break;
case 'report_add':if(!isPres()&&!inMin(p.channel))throw new Error('Нет доступа к каналу');S.reports[p.channel].push({id:uid(),...p,...by,t:Date.now()});break;
case 'report_delete':for(const k of Object.keys(MIN)){const r=S.reports[k].find(x=>x.id===p.id);if(r){if(!isPres()&&r.author_id!==session.user.id)throw new Error('Нет доступа');S.reports[k]=S.reports[k].filter(x=>x.id!==p.id)}}break;
case 'complaint_add':S.complaints.push({id:uid(),...p,...by,t:Date.now(),n:Math.max(0,...S.complaints.map(x=>x.n))+1,st:'new'});break;
case 'complaint_update':if(!canJudge())throw new Error('Нет доступа');Object.assign(S.complaints.find(x=>x.id===p.id),p,{judge:me});break;
case 'complaint_delete':if(!isPres())throw new Error('Нет доступа');S.complaints=S.complaints.filter(x=>x.id!==p.id);break;
case 'tax_save':case 'tax_import':case 'tax_delete':if(!canTax())throw new Error('Нет доступа');if(a==='tax_delete')S.taxes=S.taxes.filter(x=>x.id!==p.id);else for(const t of a==='tax_import'?p.rows:[p]){const old=S.taxes.find(x=>x.id===t.id||x.num===t.num);if(old)Object.assign(old,t);else S.taxes.push({...t,id:uid()})}break;
case 'role_set':if(!isPres())throw new Error('Нет доступа');const u=S.players.find(x=>x.id===p.id);if(p.head)S.players.forEach(x=>{if(x.min===p.min)x.head=false});Object.assign(u,{min:p.min,head:p.head});break;
case 'settings_save':if(!isPres())throw new Error('Нет доступа');Object.assign(S.settings,p,{term:p.term?new Date(new Date(p.term).getTime()+3*3600e3).toISOString().slice(0,16):''});break;
case 'transfer':if(!isPres())throw new Error('Нет доступа');S.settings.president_id=p.id;S.settings.pres=S.players.find(x=>x.id===p.id).nick;break;
default:throw new Error('Неизвестная операция')}}
function loginModal(){if(DEMO){modal('<div class="h2">Демо-вход</div><p class="fieldhint">Локальная демонстрация без настоящих паролей. Для общего сайта подключите Supabase.</p><label>Локальный профиль</label><select id="demoRole" '+(!S.players.length?'disabled':'')+'>'+(S.players.length?'':'<option value="">Нет локальных профилей</option>')+S.players.map(p=>`<option value="${esc(p.id)}">${esc(p.nick)} · ${p.id===S.settings.president_id?'Президент':MIN[p.min]?.n||'Игрок'}</option>`).join('')+'</select><div class="auth-actions"><button class="btn" onclick="demoLogin()" '+(!S.players.length?'disabled':'')+'>Открыть кабинет</button><button class="btn ghost" onclick="closeModal();go(\'register\')">Создать демо-профиль</button></div>');return}modal(`<div class="h2">Вход на сайт</div><p class="fieldhint">Используйте почту и пароль вашего аккаунта.</p><form onsubmit="event.preventDefault();doLogin(false)"><label for="lEmail">Почта</label><input id="lEmail" type="email" autocomplete="email" required><label for="lPass">Пароль</label><input id="lPass" type="password" autocomplete="current-password" required><div class="auth-actions"><button class="btn" type="submit">Войти</button><button class="btn ghost" type="button" onclick="closeModal();go('register')">Регистрация</button><button class="btn ghost" type="button" onclick="forgotPassword()">Забыли пароль?</button></div><p id="authError" class="error" role="alert" style="margin-top:12px"></p></form>`)}
async function demoLogin(){const selected=$('#demoRole')?.value;if(!S.players.some(p=>p.id===selected))return toast('Сначала создайте локальный профиль');session={user:{id:$('#demoRole').value}};sessionStorage.setItem(KEY+'_demo',session.user.id);await loadData();closeModal();route();toast('Демо-кабинет открыт')}
async function doLogin(signup=false){if(signup){closeModal();go('register');return}if(busy)return;const email=$('#lEmail').value.trim(),password=$('#lPass').value;if(!$('#lEmail').checkValidity()||!email||!password){$('#authError').textContent='Укажите корректную почту и пароль.';return}busy=true;const button=$('#modalBody button[type=submit]');if(button)button.disabled=true;try{const out=await auth('token?grant_type=password',{email,password});if(!out.access_token)throw new Error('Сервер не вернул сессию');storeAuth({...out,expires_at:Math.floor(Date.now()/1000)+out.expires_in});await loadData();closeModal();go('cabinet');route();toast('Вход выполнен')}catch(e){if($('#authError'))$('#authError').textContent='Не удалось войти: '+e.message}finally{busy=false;if(button)button.disabled=false}}
async function logout(){sessionStorage.removeItem(discordPendingKey());discordFlash='';discordFlashError=false;try{if(!DEMO&&session?.access_token)await auth('logout',{},await validToken())}catch{}if(DEMO)sessionStorage.removeItem(KEY+'_demo');else storeAuth(null);session=null;me=null;if(!DEMO){S.reports={inf:[],eco:[],bez:[]};S.lawDraft=null;S.complaints=[];S.complaintMessages=[];S.tasks=[];S.notifications=[];S.audit=[];route()}await refreshPortal();go('home')}
async function forgotPassword(){try{const email=$('#lEmail').value.trim();if(!email||!$('#lEmail').checkValidity())throw new Error('Введите почту');await auth('recover',{email});$('#authError').textContent='Если аккаунт существует, письмо восстановления отправлено.'}catch(e){$('#authError').textContent=e.message}}
function passwordModal(){if(DEMO)return toast('В демо нет настоящих паролей');modal('<div class="h2">Новый пароль</div><label>Не менее 8 символов</label><input id="newPassword" type="password" autocomplete="new-password"><button class="btn" style="margin-top:16px" onclick="changePassword()">Сохранить пароль</button>')}
async function changePassword(){const password=$('#newPassword').value;if(password.length<8)return toast('Минимум 8 символов');try{const r=await fetch(config.supabaseUrl+'/auth/v1/user',{method:'PUT',headers:{apikey:config.supabaseAnonKey,Authorization:'Bearer '+await validToken(),'Content-Type':'application/json'},body:JSON.stringify({password})});const d=await r.json();if(!r.ok)throw new Error(d.msg||'Не удалось изменить пароль');authRecovery=false;closeModal();toast('Пароль изменён')}catch(e){toast(e.message)}}
async function addNews(){openEditor('news')}
