async function addComplaint(){if(!me)return loginModal();const target=$('#cTarget').value.trim(),text=$('#cText').value.trim(),proof=$('#cProof').value.trim();if(!target||!text)return toast('Укажите цель и суть жалобы');if(proof&&safeUrl(proof)==='#')return toast('Нужна ссылка http:// или https://');const images=readImageFields('cImages');if(images===null)return;if(await mutate('complaint_add',{type:cType,target,text,proof,images})){$('#cText').value=$('#cProof').value=$('#cImages').value='';previewImageFields('cImages');renderCTarget();toast('Жалоба отправлена')}}
