async function saveTax(id){const v={nick:$('#xNick').value.trim(),num:$('#xNum').value.trim(),upd:$('#xUpd').value,paid:$('#xPaid').checked,note:$('#xNote').value.trim(),images:readImageFields('taxImages')};if(v.images===null)return;if(!/^[A-Za-z0-9_]{2,16}$/.test(v.nick)||!v.num||!v.upd)return toast('Проверьте ник, номер и дату');if(await mutate('tax_save',{...v,...(id?{id}:{})}))closeModal()}
