function renderTaxes(){
  const all=S.taxes.map(t=>({...t,...taxInfo(t)}));
  const c={act:0,soon:0,exp:0};all.forEach(t=>c[t.st]++);
  $('#taxStats').innerHTML=[[all.length,'Всего бочек','var(--txt)'],[c.act,'Активна','var(--eco)'],[c.soon,'Истекает ≤ 2 дн.','var(--gold)'],[c.exp,'Истекла','var(--bez)']].map(x=>`<div class="stat"><b style="color:${x[2]}">${x[0]}</b><span>${x[1]}</span></div>`).join('');
  $('#tAddBtn').style.display=canTax()?'':'none';$('#tImportBtn').style.display=canTax()?'':'none';
  const q=($('#tSearch').value||'').toLowerCase(),f=$('#tFilter').value;
  const l=all.filter(t=>(t.nick+' '+t.num).toLowerCase().includes(q)&&(f==='all'||t.st===f)).sort((a,b)=>a.left-b.left);
  const lbl={act:['Активна','st-ok'],soon:['Скоро истекает','st-work'],exp:['Истекла','t-bez']};
  $('#taxBody').innerHTML=l.length?l.map(t=>{
    const pct=Math.max(0,Math.min(100,t.left/7*100)), col=t.st==='act'?'var(--eco)':t.st==='soon'?'var(--gold)':'var(--bez)';
    const lt=!t.paid?'не оплачено':t.left>0?`${t.left} дн.`:t.left===0?'сегодня истекло':`${-t.left} дн. назад`;
    return `<tr><td><div class="row" style="gap:10px;flex-wrap:nowrap">${ava(t.nick)}<b>${esc(t.nick)}</b></div></td><td class="num">${esc(t.num)}</td><td>${fmtD(t.upd)}</td><td>${fmtD(t.end)}</td>
     <td><div class="small" style="margin-bottom:6px;color:${col}">${lt}</div><div class="bar"><i style="width:${t.paid?pct:0}%;background:${col}"></i></div></td>
     <td><span class="tag ${lbl[t.st][1]}"><span class="dot"></span>${lbl[t.st][0]}</span></td><td class="muted small">${esc(t.note)||'—'}${t.images?.length?`<button class="btn ghost sm tax-photo-button" onclick="showTaxImages('${t.id}')">${icon('eye')}Фото (${t.images.length})</button>`:''}</td>
     <td>${canTax()?`<div class="row" style="flex-wrap:nowrap;gap:6px"><button class="btn sm" title="Оплачено сегодня, +7 дней" onclick="extend('${t.id}')">+7 дн.</button><button class="btn ghost sm" onclick="openTax('${t.id}')">Изм.</button><button class="btn red sm" onclick="delTax('${t.id}')">Удалить</button></div>`:''}</td></tr>`}).join('')
    :`<tr><td colspan="8"><div class="empty">Ничего не найдено</div></td></tr>`;
  $$('#taxBody tr').forEach(row=>[...row.cells].forEach((cell,i)=>cell.dataset.label=['Игрок','Номер','Обновлено','Действует до','Осталось','Статус','Доп. сведения','Действия'][i]));
}
