function tick(){
  if(!S.settings.president_id||!S.settings.term||!Number.isFinite(new Date(S.settings.term+':00+03:00').getTime())){$('#timer').textContent='—';$('#timer').title='Срок полномочий не задан';return}
  $('#timer').title='Срок полномочий · МСК';
  const d=Math.max(0,new Date(S.settings.term?S.settings.term+':00+03:00':0)-Date.now())/1000||0;
  const p=n=>String(Math.floor(n)).padStart(2,'0');
  $('#timer').textContent=`${p(d/86400)} дн · ${p(d%86400/3600)} ч`;
}
