function decorateUI(){
 $('#reportsLink').hidden=!canReports();
 $$('.links a').forEach(a=>{const name=a.dataset.p;a.innerHTML=icon(name)+`<span>${a.textContent}</span>`});
 $('.burger').innerHTML=icon('menu');
 $('.statusline button').innerHTML=icon('refresh')+'Обновить';
 $('#newsActions button').innerHTML=icon('plus')+'Новая публикация';
 $('#lawActions button').innerHTML=icon('edit')+'Редактировать';
 $('#tImportBtn').innerHTML=icon('upload')+'Импорт XLSX';
 $('#tAddBtn').innerHTML=icon('plus')+'Добавить бочку';
 $('#modal').addEventListener('click',e=>{if(e.target===$('#modal'))closeModal()});
}
function toolbar(){return `<div class="editor-tools" role="toolbar" aria-label="Форматирование текста">
 <button title="Жирный (Ctrl+B)" aria-label="Жирный" onclick="editorFormat('bold')"><b>B</b></button><button title="Курсив (Ctrl+I)" aria-label="Курсив" onclick="editorFormat('italic')"><i>I</i></button><button title="Подчёркнутый (Ctrl+U)" aria-label="Подчёркнутый" onclick="editorFormat('underline')"><u>U</u></button><button title="Зачёркнутый" aria-label="Зачёркнутый" onclick="editorFormat('strike')"><s>S</s></button><span class="tool-sep"></span><button title="Заголовок" aria-label="Заголовок" onclick="editorFormat('heading')">H</button><button title="Цитата" aria-label="Цитата" onclick="editorFormat('quote')">${icon('quote')}</button><button title="Список" aria-label="Список" onclick="editorFormat('list')">${icon('list')}</button><button title="Код" aria-label="Код" onclick="editorFormat('code')">&lt;/&gt;</button><button title="Ссылка" aria-label="Ссылка" onclick="editorFormat('link')">${icon('link')}</button><button title="Спойлер" aria-label="Спойлер" onclick="editorFormat('spoiler')">${icon('eye')}</button></div>`}
function openEditor(kind,id){
 if(kind==='report'?!canReports():!isPres())return toast('Нет доступа к редактору');
 const source=kind==='report'?(id?Object.values(S.reports).flat().find(r=>r.id===id):{title:'',text:''}):kind==='law'?(S.lawDraft||S.law||{title:'Конституция государства',text:''}):S.news.find(n=>n.id===id)||{title:'',text:''};
 if(!source||(kind==='report'&&id&&!canEditReport(source)))return toast('Нет доступа к этому отчёту');editor={kind,id:id||null,channel:kind==='report'?(source.channel||chan):null,images:[...(source.images||[])],uploading:false};
 modal(`<div class="editor-heading"><div><div class="eyebrow section-label">${kind==='report'?MIN[editor.channel].full:kind==='law'?'ОСНОВНОЙ ЗАКОН':'КАНЦЕЛЯРИЯ ПРЕЗИДЕНТА'}</div><h2>${kind==='report'?(id?'Редактирование отчёта':'Новый отчёт'):kind==='law'?'Редактор конституции':id?'Редактирование новости':'Новая публикация'}</h2></div><span class="tag t-pl">${icon('lock')}${kind==='report'?'Закрытый канал':'Только Президент'}</span></div>
 <div class="editor-grid"><div class="editor-fields">${kind==='news'?`<div class="editor-options decree-options"><div><label for="eKind">Тип документа</label><select id="eKind" onchange="updateDecreeFields()"><option value="news" ${source.kind!=='decree'?'selected':''}>Новость</option><option value="decree" ${source.kind==='decree'?'selected':''}>Указ</option></select></div><div id="decreeNoWrap" ${source.kind==='decree'?'':'hidden'}><label for="eDecreeNo">Номер указа</label><input id="eDecreeNo" maxlength="40" value="${esc(source.decree_no||'')}" placeholder="Например: 12/2026"></div></div>`:''}<label for="eTitle">Заголовок</label><input id="eTitle" maxlength="180" value="${esc(source.title)}" placeholder="Заголовок публикации" oninput="updateEditorPreview()"><label for="eText">Текст · Markdown как в Discord</label>${toolbar()}<textarea id="eText" maxlength="${kind==='law'?50000:20000}" placeholder="Напишите текст. Выделите фрагмент и нажмите кнопку форматирования." oninput="updateEditorPreview()">${esc(source.text)}</textarea>
 <div class="editor-options"><div><label for="eAccent">Цвет карточки</label><input id="eAccent" type="color" value="${/^#[0-9a-f]{6}$/i.test(source.accent||'')?source.accent:'#a5a8b8'}" oninput="updateEditorPreview()"></div><div><label for="eFooter">Подпись внизу</label><input id="eFooter" maxlength="200" value="${esc(source.footer||'')}" placeholder="Например: Указ № 12" oninput="updateEditorPreview()"></div></div>
 <label>Фото · до 4 изображений</label><div class="image-controls"><input id="eImageUrl" type="url" placeholder="https://.../photo.png" aria-label="Ссылка на фото"><button class="btn ghost sm" onclick="addEditorImage()">Добавить ссылку</button><label ${kind==='report'?'hidden':''} class="btn ghost sm upload-label" for="eUpload">${icon('upload')}С устройства</label><input id="eUpload" type="file" accept="image/png,image/jpeg,image/webp,image/gif" multiple hidden onchange="uploadEditorImages(this)"></div><p class="fieldhint">PNG, JPG, WebP, GIF · до 5 МБ на фото. Внешняя ссылка должна быть HTTPS. ${kind==='report'?'В отчётах используются внешние HTTPS-ссылки. Доступ к самому файлу регулируется сервисом, где он размещён.':'Загрузка с устройства требует настройки хранилища Supabase.'}</p><div id="editorImages"></div><p id="editorUploadStatus" class="fieldhint" role="status"></p>
 ${kind==='news'?`<label class="row" style="color:var(--txt)"><input type="checkbox" id="ePin" style="width:auto" ${source.pin?'checked':''} onchange="updateEditorPreview()"> Закрепить новость</label>`:''}
 </div><div class="editor-preview"><div class="preview-label">${icon('eye')}Предпросмотр публикации</div><div id="editorPreview"></div></div></div>
 <div class="editor-bottom"><span class="fieldhint">HTML и скрипты не исполняются</span><span class="sp"></span>${kind==='law'?'<button class="btn ghost" id="draftSaveButton" onclick="saveEditor(true)">Сохранить черновик</button>':''}<button class="btn ghost" onclick="closeModal()">Отмена</button><button class="btn" id="publishButton" onclick="saveEditor(false)">${icon('send')}${kind==='law'?'Опубликовать закон':id?'Сохранить изменения':kind==='report'?'Отправить отчёт':'Опубликовать'}</button></div>`);
 $('#modalBody').classList.add('editor-modal');renderEditorImages();updateEditorPreview();
 $('#eText').addEventListener('keydown',e=>{if((e.ctrlKey||e.metaKey)&&['b','i','u'].includes(e.key.toLowerCase())){e.preventDefault();editorFormat({b:'bold',i:'italic',u:'underline'}[e.key.toLowerCase()])}if((e.ctrlKey||e.metaKey)&&e.key==='Enter'){e.preventDefault();saveEditor(false)}});
}
function editorFormat(type){const ta=$('#eText');if(!ta)return;const a=ta.selectionStart,b=ta.selectionEnd,selection=ta.value.slice(a,b)||'текст';let insert='';const pairs={bold:['**','**'],italic:['*','*'],underline:['__','__'],strike:['~~','~~'],code:['`','`'],spoiler:['||','||']};if(pairs[type])insert=pairs[type][0]+selection+pairs[type][1];else if(type==='heading')insert='\n## '+selection+'\n';else if(type==='quote')insert='\n'+selection.split('\n').map(l=>'> '+l).join('\n')+'\n';else if(type==='list')insert='\n'+selection.split('\n').map(l=>'- '+l).join('\n')+'\n';else if(type==='link'){const url=prompt('HTTPS-ссылка:','https://');if(!url||!/^https:\/\//.test(url)||safeUrl(url)==='#')return;insert='['+selection+']('+url+')'}ta.setRangeText(insert,a,b,'end');ta.focus();updateEditorPreview();}
function editorValues(){return {title:$('#eTitle').value.trim(),text:$('#eText').value.trim(),images:editor.images,accent:$('#eAccent').value,footer:$('#eFooter').value.trim(),...(editor.kind==='news'?{pin:$('#ePin').checked,kind:$('#eKind').value,decree_no:$('#eKind').value==='decree'?$('#eDecreeNo').value.trim():null}:{})}}
function updateEditorPreview(){if(!editor||!$('#editorPreview'))return;const v=editorValues();$('#editorPreview').innerHTML=embedCard({...v,author:editor.kind==='report'?me:S.settings.pres,t:Date.now()},{law:editor.kind==='law',report:editor.kind==='report'});}
function renderEditorImages(){if(!editor)return;$('#editorImages').innerHTML=editor.images.map((src,i)=>`<div class="editor-image-item"><img src="${esc(imageUrl(src))}" alt="Прикреплённое фото ${i+1}" onerror="this.style.visibility='hidden'"><span>Фото ${i+1}</span><button class="btn ghost sm" aria-label="Удалить фото ${i+1}" onclick="editor.images.splice(${i},1);renderEditorImages();updateEditorPreview()">${icon('close')}</button></div>`).join('');}
function addEditorImage(){if(!editor)return;if(editor.images.length>=4)return toast('Можно прикрепить до 4 фото');const src=imageUrl($('#eImageUrl').value.trim());if(!src||!src.startsWith('https:'))return toast('Укажите HTTPS-ссылку на изображение');editor.images.push(src);$('#eImageUrl').value='';renderEditorImages();updateEditorPreview();}
async function uploadEditorImages(input){if(editor?.kind==='report')return toast('Для отчёта добавьте HTTPS-ссылку на изображение');if(!editor||editor.uploading)return;const state=editor,files=[...input.files];if(state.images.length+files.length>4)return toast('Всего можно прикрепить до 4 фото');if(files.some(f=>!['image/png','image/jpeg','image/webp','image/gif'].includes(f.type)||f.size>5*1024*1024))return toast('Нужны PNG/JPG/WebP/GIF, каждый до 5 МБ');state.uploading=true;$('#publishButton').disabled=true;$('#draftSaveButton')?.setAttribute('disabled','');try{for(const file of files){let src;if(DEMO){if(file.size>700*1024)throw new Error('В локальном демо фото с устройства ограничено 700 КБ из-за хранилища браузера. Для больших фото используйте ссылку.');src=await new Promise((resolve,reject)=>{const r=new FileReader();r.onload=()=>resolve(r.result);r.onerror=reject;r.readAsDataURL(file)})}else{const token=await validToken();if(!token)throw new Error('Войдите в аккаунт');const ext={'image/png':'png','image/jpeg':'jpg','image/webp':'webp','image/gif':'gif'}[file.type],name=uid()+'.'+ext;const r=await fetch(config.supabaseUrl+'/storage/v1/object/portal-media/'+name,{method:'POST',headers:{apikey:config.supabaseAnonKey,Authorization:'Bearer '+token,'Content-Type':file.type},body:file});if(!r.ok){const d=await r.json().catch(()=>({}));throw new Error(d.message||'Загрузка не выполнена. Проверьте SQL-миграцию и bucket portal-media.')}src=config.supabaseUrl+'/storage/v1/object/public/portal-media/'+name;}state.images.push(src);if(editor===state&&$('#editorUploadStatus'))$('#editorUploadStatus').textContent='Загружено фото: '+state.images.length;}if(editor===state){renderEditorImages();updateEditorPreview()}}catch(e){toast(e.message);if(editor===state&&$('#editorUploadStatus'))$('#editorUploadStatus').textContent='Ошибка: '+e.message;}finally{state.uploading=false;if(editor===state&&$('#publishButton')){$('#publishButton').disabled=false;$('#draftSaveButton')?.removeAttribute('disabled')}input.value='';}}
async function saveEditor(draft){if(!editor||editor.uploading||busy)return;const v=editorValues();if(!v.title||!v.text)return toast('Заполните заголовок и текст');if(v.images.some(src=>!imageUrl(src)))return toast('Проверьте ссылки на изображения');if(editor.kind==='news'&&v.kind==='decree'&&!v.decree_no)return toast('Укажите номер указа');const state=editor,action=state.kind==='law'?(draft?'law_draft':'law_publish'):state.kind==='report'?(state.id?'report_update':'report_add'):(state.id?'news_update':'news_add');if(state.kind==='law'&&!draft&&!confirm('Опубликовать эту редакцию конституции для всех жителей?'))return;if(await mutate(action,{...v,...(state.id?{id:state.id}:{}),...(state.kind==='report'?{channel:state.channel}:{})})){if(draft){toast('Черновик сохранён. Жители видят прежнюю опубликованную редакцию.')}else{closeModal();toast(state.kind==='law'?'Конституция опубликована':'Публикация сохранена')}}}

initV3();
